   104→  private final Spec spec;
   105→  private final Set<SlotProposerIndexAndColumnIndex> receivedValidDataColumnSidecarInfoSet;
   106→  private final Set<InclusionProofInfo> validInclusionProofInfoSet;
   107→  private final Set<Bytes32> validSignedBlockHeaders;
   108→  private final GossipValidationHelper gossipValidationHelper;
   109→  private final Map<Bytes32, BlockImportResult> invalidBlockRoots;
   110→  private final MiscHelpersFulu miscHelpersFulu;
   111→  private final KZG kzg;
   112→  private final Counter totalDataColumnSidecarsProcessingRequestsCounter;
   113→  private final Counter totalDataColumnSidecarsProcessingSuccessesCounter;
   114→  private final MetricsHistogram dataColumnSidecarInclusionProofVerificationTimeSeconds;
   115→  private final MetricsHistogram dataColumnSidecarKzgBatchVerificationTimeSeconds;
   116→
   117→  public static DataColumnSidecarGossipValidator create(
   118→      final Spec spec,
   119→      final Map<Bytes32, BlockImportResult> invalidBlockRoots,
   120→      final GossipValidationHelper validationHelper,
   121→      final MiscHelpersFulu miscHelpersFulu,
   122→      final KZG kzg,
   123→      final MetricsSystem metricsSystem,
   124→      final TimeProvider timeProvider) {
   125→
   126→    final Optional<Integer> maybeNumberOfColumns = spec.getNumberOfDataColumns();
   127→
   128→    final int validInfoSize = VALID_BLOCK_SET_SIZE * maybeNumberOfColumns.orElse(1);
   129→    // It's not fatal if we miss something and we don't need finalized data
   130→    final int validSignedBlockHeadersSize =
   131→        spec.getGenesisSpec().getSlotsPerEpoch() * BEST_CASE_NON_FINALIZED_EPOCHS;
   132→
   133→    return new DataColumnSidecarGossipValidator(
   134→        spec,
   135→        invalidBlockRoots,
   136→        validationHelper,
   137→        miscHelpersFulu,
   138→        kzg,
   139→        metricsSystem,
   140→        timeProvider,
   141→        LimitedSet.createSynchronized(validInfoSize),
   142→        LimitedSet.createSynchronized(validSignedBlockHeadersSize),
   143→        LimitedSet.createSynchronized(validSignedBlockHeadersSize));
   144→  }
   145→
   146→  @VisibleForTesting
   147→  public Set<SlotProposerIndexAndColumnIndex> getReceivedValidDataColumnSidecarInfoSet() {
   148→    return receivedValidDataColumnSidecarInfoSet;
   149→  }
   150→
   151→  private DataColumnSidecarGossipValidator(
   152→      final Spec spec,
   153→      final Map<Bytes32, BlockImportResult> invalidBlockRoots,
   154→      final GossipValidationHelper gossipValidationHelper,
   155→      final MiscHelpersFulu miscHelpersFulu,
   156→      final KZG kzg,
   157→      final MetricsSystem metricsSystem,
   158→      final TimeProvider timeProvider,
   159→      final Set<SlotProposerIndexAndColumnIndex> receivedValidDataColumnSidecarInfoSet,
   160→      final Set<InclusionProofInfo> validInclusionProofInfoSet,
   161→      final Set<Bytes32> validSignedBlockHeaders) {
   162→    this.spec = spec;
   163→    this.invalidBlockRoots = invalidBlockRoots;
   164→    this.gossipValidationHelper = gossipValidationHelper;
   165→    this.miscHelpersFulu = miscHelpersFulu;
   166→    this.kzg = kzg;
   167→    this.receivedValidDataColumnSidecarInfoSet = receivedValidDataColumnSidecarInfoSet;
   168→    this.totalDataColumnSidecarsProcessingRequestsCounter =
   169→        metricsSystem.createCounter(
   170→            TekuMetricCategory.BEACON,
   171→            "data_column_sidecar_processing_requests_total",
   172→            "Total number of data column sidecars submitted for processing");
   173→    this.totalDataColumnSidecarsProcessingSuccessesCounter =
   174→        metricsSystem.createCounter(
   175→            TekuMetricCategory.BEACON,
   176→            "data_column_sidecar_processing_successes_total",
   177→            "Total number of data column sidecars verified for gossip");
   178→    this.dataColumnSidecarInclusionProofVerificationTimeSeconds =
   179→        DATA_COLUMN_SIDECAR_INCLUSION_PROOF_VERIFICATION_HISTOGRAM.apply(
   180→            metricsSystem, timeProvider);
   181→    this.dataColumnSidecarKzgBatchVerificationTimeSeconds =
   182→        DATA_COLUMN_SIDECAR_KZG_BATCH_VERIFICATION_HISTOGRAM.apply(metricsSystem, timeProvider);
   183→
   184→    this.validInclusionProofInfoSet = validInclusionProofInfoSet;
   185→    this.validSignedBlockHeaders = validSignedBlockHeaders;
