   122→  @Override
   123→  public void onSlot(final UInt64 slot) {
   124→    if (shouldSkipProcessing(slot)) {
   125→      return;
   126→    }
   127→    asyncRunner
   128→        .runAfterDelay(
   129→            () -> {
   130→              LOG.debug("Check if recovery needed for slot: {}", slot);
   131→
   132→              recoveryTasks.keySet().stream()
   133→                  .filter(key -> key.getSlot().isLessThanOrEqualTo(slot))
   134→                  .map(recoveryTasks::get)
   135→                  .forEach(
   136→                      recoveryTask -> {
   137→                        if (recoveryTask.timedOut().compareAndSet(false, true)) {
   138→                          maybeStartRecovery(recoveryTask);
   139→                        }
   140→                      });
   141→            },
   142→            slotToRecoveryDelay.apply(slot))
   143→        .finishWarn(LOG);
   144→  }
   145→
   146→  private boolean shouldSkipProcessing(final UInt64 slot) {
   147→    if (isActiveSuperNode(slot)) {
   148→      return false;
   149→    }
   150→    if (custodyGroupCountManagerSupplier.get().getCustodyGroupCount() == groupCount) {
   151→      if (!isSuperNode.get()) {
   152→        LOG.debug(
   153→            "Number of required custody groups reached maximum. Activating super node reconstruction.");
   154→        isSuperNode.set(true);
   155→      }
   156→      return false;
   157→    }
   158→    return true;
   159→  }
   160→
   161→  protected void maybeStartRecovery(final RecoveryTask task) {
   162→    if (readyToBeRecovered(task)) {
   163→      if (task.recoveryStarted.compareAndSet(false, true)) {
   164→        if (task.existingSidecars.size() == columnCount) {
   165→          task.existingSidecars.clear();
   166→          return;
   167→        }
   168→        scheduleRecoveryTask(task);
   169→      }
   170→    }
   171→  }
   172→
   173→  @VisibleForTesting
   174→  protected void scheduleRecoveryTask(final RecoveryTask task) {
   175→    asyncRunner
   176→        .runAsync(() -> prepareAndInitiateRecovery(task))
   177→        .whenException(
   178→            ex -> {
   179→              LOG.debug(
   180→                  "Error during recovery of {} task with {} sidecars",
   181→                  task.slotAndBlockRoot,
   182→                  task.existingSidecars.size(),
   183→                  ex);
   184→              // release task for future retries only if error happened during recovery
   185→              task.recoveryStarted.set(false);
   186→            })
   187→        .finishError(LOG);
   188→  }
   189→
   190→  private boolean readyToBeRecovered(final RecoveryTask task) {
   191→    if (task.recoveryStarted().get()) {
   192→      // already started
   193→      return false;
   194→    }
   195→
   196→    if (!task.timedOut().get()) {
   197→      return false;
   198→    }
   199→
   200→    if (task.existingSidecars().size() < recoverColumnCount) {
   201→      // not enough columns collected
   202→      return false;
   203→    }
   204→
   205→    return true;
   206→  }
   207→
   208→  @Override
   209→  public void subscribeToValidDataColumnSidecars(
   210→      final DataColumnSidecarManager.ValidDataColumnSidecarsListener sidecarsListener) {
   211→    validDataColumnSidecarsSubscribers.subscribe(sidecarsListener);
   212→  }
   213→
   214→  private boolean isActiveSuperNode(final UInt64 slot) {
   215→    return isSuperNode.get()
   216→        && spec.atSlot(slot).getMilestone().isGreaterThanOrEqualTo(SpecMilestone.FULU);
   217→  }
   218→
   219→  protected record RecoveryTask(
   220→      SlotAndBlockRoot slotAndBlockRoot,
   221→      Map<DataColumnSlotAndIdentifier, DataColumnSidecar> existingSidecars,
   222→      AtomicBoolean recoveryStarted,
   223→      AtomicBoolean timedOut) {}
   224→
   225→  private void prepareAndInitiateRecovery(final RecoveryTask task) {
